// Nodo Code: "Parsear Refinamiento" (Ruta B)
// ---------------------------------------------------------------------------
// Limpia markdown fences del output del Agente de Refinamiento, parsea el JSON
// con fallback a steps_to_run='all', incrementa revision_count y persiste el
// session_state actualizado. Ver doc de arquitectura, seccion 4.3.

const incoming = $input.first().json;

// El agente (toolsAgent) deja su salida en .output (string) o, segun version,
// directamente como objeto. Soportamos ambos.
let raw = incoming.output ?? incoming.text ?? incoming.response ?? incoming;

// Recuperar contexto previo: el item entrante deberia arrastrar session_id /
// current_session, pero por robustez los recuperamos tambien del static data.
const store = $getWorkflowStaticData('global');
const sessions = store.sessions || {};

// Intentar localizar session_id desde el input o desde el JSON del agente.
let session_id = incoming.session_id || null;

function stripFences(s) {
  if (typeof s !== 'string') return s;
  return s
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

let parsed = null;
let parseFailed = false;

if (typeof raw === 'string') {
  try {
    parsed = JSON.parse(stripFences(raw));
  } catch (e) {
    parseFailed = true;
  }
} else if (raw && typeof raw === 'object') {
  parsed = raw;
}

// Recuperar la sesion previa para tener una base sobre la que aplicar cambios.
if (!session_id && parsed && parsed.session_id) session_id = parsed.session_id;
const prev = session_id ? sessions[session_id] : null;
const prevBrief = prev?.travel_brief || {};
const prevRevision = Number(prev?.revision_count ?? 0);

// Fallback: si el parse fallo o el agente no devolvio un travel_brief usable,
// re-ejecutamos todo conservando el brief anterior.
if (parseFailed || !parsed || typeof parsed !== 'object') {
  parsed = {
    session_id,
    steps_to_run: 'all',
    feedback_instruction: 'fallback: no se pudo interpretar la instruccion',
    travel_brief: prevBrief,
    revision_count: prevRevision + 1,
  };
}

// Normalizar campos esperados.
const steps_to_run = parsed.steps_to_run || 'all';
const feedback_instruction =
  parsed.feedback_instruction || incoming.feedback_text || 'refinamiento';
const travel_brief = parsed.travel_brief || prevBrief;
session_id = parsed.session_id || session_id;

// Construir session_state actualizado y persistirlo.
const updated = {
  session_id,
  status: 'awaiting_search',
  revision_count: prevRevision + 1,
  updated_at: new Date().toISOString(),
  travel_brief,
  current_plan: prev?.current_plan || null,
};

if (session_id) {
  if (!store.sessions) store.sessions = {};
  store.sessions[session_id] = updated;
}

return [
  {
    json: {
      _error: false,
      route: 'refinamiento',
      session_id,
      session_state: updated,
      steps_to_run,
      feedback_instruction,
      existing_plan: updated.current_plan,
      revision_count: updated.revision_count,
    },
  },
];

// Nodo Code: "Preparar Motor Planificador" (compartido Ruta A + Ruta B)
// ---------------------------------------------------------------------------
// Unifica la entrada de ambas rutas. Construye segments[] (soporta multi-
// destino). Extrae steps_to_run, existing_plan y feedback_instruction para
// pasarlos al Agente Motor. Ver doc de arquitectura, seccion 4.4.

const incoming = $input.first().json;

// session_state puede venir de "Validar Formulario" (Ruta A) o de
// "Parsear Refinamiento" (Ruta B).
const session_state = incoming.session_state;
if (!session_state || !session_state.travel_brief) {
  throw new Error('Preparar Motor: falta session_state.travel_brief en la entrada');
}

const brief = session_state.travel_brief;
const session_id = session_state.session_id;

// Ruta A => ejecucion inicial completa. Ruta B => valores del refinamiento.
const isRefine = incoming.route === 'refinamiento';
const steps_to_run = isRefine ? incoming.steps_to_run || 'all' : 'all';
const feedback_instruction = isRefine
  ? incoming.feedback_instruction || 'refinamiento'
  : '';
const existing_plan = isRefine ? incoming.existing_plan || null : null;
const revision_count = Number(
  isRefine ? incoming.revision_count ?? session_state.revision_count ?? 0 : 0,
);

// Construir segments[] (un segmento por destino para soporte multi-ciudad).
const destinations = Array.isArray(brief.destination_city)
  ? brief.destination_city
  : [brief.destination_city];

const segments = destinations.map((dest, idx) => ({
  segment_index: idx,
  origin: idx === 0 ? brief.origin_city : destinations[idx - 1],
  destination: dest,
}));

// Lista de destinos unicos para las consultas Tavily.
const unique_destinations = [...new Set(destinations)];

return [
  {
    json: {
      session_id,
      session_state,
      segments,
      unique_destinations,
      steps_to_run,
      feedback_instruction,
      existing_plan,
      revision_count,
    },
  },
];

